import{_ as n,l,o as e,c as i,v as o,p as s,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"边际消费倾向异质","description":"","frontmatter":{"title":"边际消费倾向异质","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/heterogeneous-mpc.md","filePath":"econ/heterogeneous-mpc.md","lastUpdated":1789023840000}'),m={name:"econ/heterogeneous-mpc.md"};function P(h,a,A,E,C,u){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="边际消费倾向异质" tabindex="-1">边际消费倾向异质 <a class="header-anchor" href="#边际消费倾向异质" aria-label="Permalink to &quot;边际消费倾向异质&quot;">​</a></h1><div class="epigraph"><p>同一美元转移，约束附近几乎吃掉，富人或流动性充足者几乎不吃——加总乘数是 MPC 的加权，不是代表性 $\\sigma$。</p><footer>—— Kaplan and Violante, A Model of the Consumption Response to Fiscal Stimulus Payments, Econometrica 2014；Parker, Souleles, Johnson and McClelland 的退税实验</footer></div><p><a href="/econ/hank">上一课</a>把间接效应的强度交给「谁的 MPC 高」。本课缺口是把 <strong>MPC 截面</strong>写成可估计、可校准的对象。不重推 Calvo，不把财政乘数整课提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RANK 的转移支付若李嘉图，MPC 近零；若一次总付且债券在无限生命代表手里，仍近欧拉。数据：退税、刺激支票的季度 MPC 常在 0.15–0.25 甚至更高（Johnson–Parker–Souleles；Parker 等 2013）。Kaplan–Violante：两资产模型制造「富却无流动性」的手到口，匹配高 MPC 与可观的净资产。缺口是：加总 MPC 不是家庭平均的偏好参数，而是分布与流动性的函数。</p><p><span class="marginnote">Kaplan and Violante, <em>Econometrica</em> 82(4), 2014, 1199–1239。Misra–Surico、Fagereng–Holm–Natvik 用挪威行政数据看 MPC 随财富下降。Auclert, <em>AER</em> 2019 充分统计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>微观：用准实验（退税时间、彩票、分红）估 \\(\\partial c/\\partial\\) 转移，按流动资产、按揭、收入分箱。宏观校准：令模型的平均 MPC 与分箱 MPC 对上，再谈脉冲。理论：不受约束者 MPC \\(\\approx r\\) 量级的小斜率；约束者接近 1（非耐久）。耐久与习惯把动态摊到多期，但仍远高于 RANK。</p>',8)),(e(),s(d,null,{default:t(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E7%BA%A6%E6%9D%9F%20%2F%20%E8%B4%AB%E6%B5%81%E5%8A%A8%22%5D%20--%3E%20HIGH%5B%22%E9%AB%98%20MPC%22%5D%0A%20%20RICH%5B%22%E6%B5%81%E5%8A%A8%E5%85%85%E8%B6%B3%22%5D%20--%3E%20LOW%5B%22%E4%BD%8E%20MPC%22%5D%0A%20%20HIGH%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%20MPC%20%3D%20%E5%8A%A0%E6%9D%83%22%5D%0A%20%20LOW%20--%3E%20AGG%0A%20%20AGG%20--%3E%20MUL%5B%22%E8%B4%A2%E6%94%BF%E4%B8%8E%E9%97%B4%E6%8E%A5%E8%B4%A7%E5%B8%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>HANK 的间接效应 \\(\\approx\\) 收入变动 \\(\\times\\) 加总 MPC。故同一劳动收入 IRF，MPC 校准错则乘数错。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是欧拉不等式与非流动性。净资产高也可以 MPC 高：住房与退休账户不能当月花。一资产模型用极紧的借贷约束硬造平均 MPC，会把财富分布压得太穷——两资产解开这个权衡。加总时，转移的<strong>指向</strong>（给谁）改变乘数，即使平均 MPC 固定。这是下一课财政 HANK 的入口。</p><p><span class="marginnote">缓冲存量课已有目标财富附近的高 MPC。本课把它接到可测的刺激支付与 HANK 加权，而不是重写谨慎系数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计最优 UBI。不把信用卡微观结构写成宏观。股票持有者的 MPC 与股权溢价无关的测量，不在此重做资产定价。企业主、创业家庭的 MPC 另口径。</p><p>后课默认：说到加总 MPC，必须说加权与流动性，而不是单一 \\(\\sigma\\)。下一课：同样的加权如何改写财政刺激。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MPC 随流动性与约束强烈异质；平均可由两资产校准。</li><li>准实验提供分箱靶，不是代表性欧拉的残差。</li><li>加权 MPC 是 HANK 乘数的充分统计之一。</li><li>出处：Kaplan and Violante, <em>Econometrica</em> 2014；Parker 等退税研究。</li></ul>',9))])}const B=n(m,[["render",P]]);export{_ as __pageData,B as default};
